from requests.utils import _parse_content_type_header

def test_parse_content_type_header():
    # Valid case
    header = "text/html; charset=utf-8"
    content_type, params = _parse_content_type_header(header)
    print(f"Test 1: {content_type=}, {params=}")
    assert content_type == "text/html"
    assert params == {"charset": "utf-8"}

    # Malformed case: missing '='
    header = "text/html; malformed"
    content_type, params = _parse_content_type_header(header)
    print(f"Test 2: {content_type=}, {params=}")
    # Current behavior: params = {"malformed": True}
    # Expected behavior: params = {}
    assert params == {}

    # Mixed case
    header = "text/html; charset=utf-8; malformed"
    content_type, params = _parse_content_type_header(header)
    print(f"Test 3: {content_type=}, {params=}")
    assert content_type == "text/html"
    assert params == {"charset": "utf-8"}

if __name__ == "__main__":
    try:
        test_parse_content_type_header()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed!")
        raise e

